/*
 * A190806  Increasing sequence generated by these rules: a(1)=1, and if x is
 *          in a then 2x-1 and 3x+2 are in a.
 * https://oeis.org/A190806
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 10, u16 n <= 714, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence a(n) = A190806: start with 1; if x is in the set then
   2x-1 and 3x+2 are also in the set. Output the increasing
   sequence with no repetitions.  */
 
#include <stdlib.h>
#include <stdint.h>

/* Forward declaration of production functions   */
static void sift_up(size_t i);
static void push_heap(seq_t val);
static seq_t pop_heap(void);

/* Heap storage – static so all helper functions can see them */
static seq_t *heap = NULL;       /* array of heap elements    */
static size_t hcap = 0;          /* current capacity         */
static size_t hsz  = 0;          /* number of elements used  */

static void sift_up(size_t i)
{
    while (i > 0) {
        size_t parent = (i - 1) >> 1;
        if (heap[parent] <= heap[i]) break;
        seq_t tmp = heap[parent];
        heap[parent] = heap[i];
        heap[i] = tmp;
        i = parent;
    }
}

static void push_heap(seq_t val)
{
    if (hsz >= hcap) {
        hcap = (hcap < 4 ? 4 : hcap << 1);
        seq_t *tmp = (seq_t *)realloc(heap, hcap * sizeof(seq_t));
        if (!tmp) {              /* allocation failure – abort */
            hsz = 0;
            return;
        }
        heap = tmp;
    }
    heap[hsz++] = val;
    sift_up(hsz - 1);
}

static seq_t pop_heap(void)
{
    if (hsz == 0) return 0;      /* should not happen */
    seq_t min = heap[0];
    seq_t last = heap[--hsz];
    if (hsz > 0) {
        heap[0] = last;
        /* sift down */
        size_t i = 0;
        while (1) {
            size_t left  = (i << 1) + 1;
            size_t right = left + 1;
            size_t smallest = i;
            if (left < hsz && heap[left] < heap[smallest]) smallest = left;
            if (right < hsz && heap[right] < heap[smallest]) smallest = right;
            if (smallest == i) break;
            seq_t tmp = heap[i];
            heap[i] = heap[smallest];
            heap[smallest] = tmp;
            i = smallest;
        }
    }
    return min;
}

/* Return the nth term of the sequence (n >= 1). */
seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;      /* offset handling */

    /* initial heap capacity – over‑allocate a bit for speed */
    hcap = (size_t)(4 * n + 10);
    heap = (seq_t *)malloc(hcap * sizeof(seq_t));
    if (!heap) return (seq_t)0;       /* allocation failure */

    hsz = 0;
    push_heap((seq_t)1);              /* seed value */

    seq_t prev = 0;
    int have_prev = 0;
    idx_t count = 0;

    while (1) {
        seq_t x = pop_heap();

        /* delete duplicates */
        if (have_prev && x == prev) continue;
        have_prev = 1;
        prev = x;
        ++count;

        if (count == n) {
            free(heap);
            return x;
        }

        /* generate successors */
        push_heap((seq_t)2 * x - (seq_t)1);
        push_heap((seq_t)3 * x + (seq_t)2);
    }
}
